```js
function sweptAABB(px, py, x, y, box) {
  // box = { x, y, w, h } expanded brick; segment from (px,py) to (x,y)
  let tEnter = 0, tExit = 1;
  // X axis
  if (x === px) {
    if (px < box.x || px > box.x + box.w) return null;
  } else {
    let t1 = (box.x - px) / (x - px);
    let t2 = (box.x + box.w - px) / (x - px);
    if (t1 > t2) [t1, t2] = [t2, t1];
    tEnter = Math.max(tEnter, t1);
    tExit = Math.min(tExit, t2);
    if (tEnter > tExit) return null;
  }
  // Y axis
  if (y === py) {
    if (py < box.y || py > box.y + box.h) return null;
  } else {
    let t1 = (box.y - py) / (y - py);
    let t2 = (box.y + box.h - py) / (y - py);
    if (t1 > t2) [t1, t2] = [t2, t1];
    tEnter = Math.max(tEnter, t1);
    tExit = Math.min(tExit, t2);
    if (tEnter > tExit) return null;
  }
  if (tEnter < 0) tEnter = 0; // already inside at start
  return { t: tEnter, x: px + (x - px) * tEnter, y: py + (y - py) * tEnter };
}
