### The swept hit function

```js
// Swept AABB test: does the ball's centre, travelling from (px, py) to
// (cx, cy), touch the brick (expanded by the radius)? Returns the contact
// point and the entry time, or null.
function sweptContact(px, py, cx, cy, r, brick) {
  const ex = brick.x - r;
  const ey = brick.y - r;
  const ew = brick.w + 2 * r;
  const eh = brick.h + 2 * r;
  const dx = cx - px;
  const dy = cy - py;

  let tEnter = 0;
  let tExit = 1;
  let enterX = null;
  let enterY = null;

  if (dx === 0) {
    if (px < ex || px > ex + ew) return null;
    enterX = 0; // hmm...
  } else {
    let t1 = (ex - px) / dx;
    let t2 = (ex + ew - px) / dx;
    if (t1 > t2) { const tmp = t1; t1 = t2; t2 = tmp; }
    enterX = t1;
    tEnter = Math.max(tEnter, t1);
    tExit = Math.min(tExit, t2);
    if (tEnter > tExit) return null;
  }

  if (dy === 0) {
    if (py < ey || py > ey + eh) return null;
    enterY = 0;
  } else {
    let t1 = (ey - py) / dy;
    let t2 = (ey + eh - py) / dy;
    if (t1 > t2) { const tmp = t1; t1 = t2; t2 = tmp; }
    enterY = t1;
    tEnter = Math.max(tEnter, t1);
    tExit = Math.min(tExit, t2);
    if (tEnter > tExit) return null;
  }

  // The entry time is the LAST slab entered.
  const t = tEnter;
  if (t > 1) return null; // hit after the move — shouldn't happen but safe
  return {
    t,
    x: px + dx * t,
    y: py + dy * t,
  };
}
```

