// --- Brick collision (issue #1) --------------------------------------------

// Swept AABB test: does the ball's centre, travelling in a straight line from
// (prevX, prevY) to its current position, touch the brick (expanded by the
// radius)? This catches the tunnelling case: at level 6 the ball can move up
// to 35.5 px per frame while a brick only takes 34 px to cross, so a discrete
// before/after test misses the brick entirely.
//
// Returns the first contact point `{ t, x, y }` (entry time in [0, 1] and the
// centre position at that moment) or `null`. Falls back to the current
// position when the ball is already overlapping (started the frame inside).
export function sweptBrickHit(prevX, prevY, ball, brick) {
  const ex = brick.x - ball.r;
  const ey = brick.y - ball.r;
  const ew = brick.w + 2 * ball.r;
  const eh = brick.h + 2 * ball.r;
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;

  let tEnter = 0;
  let tExit = 1;

  if (dx === 0) {
    if (prevX < ex || prevX > ex + ew) return null;
  } else {
    let t1 = (ex - prevX) / dx;
    let t2 = (ex + ew - prevX) / dx;
    if (t1 > t2) [t1, t2] = [t2, t1];
    tEnter = Math.max(tEnter, t1);
    tExit = Math.min(tExit, t2);
    if (tEnter > tExit) return null;
  }

  if (dy === 0) {
    if (prevY < ey || prevY > ey + eh) return null;
  } else {
    let t1 = (ey - prevY) / dy;
    let t2 = (ey + eh - prevY) / dy;
    if (t1 > t2) [t1, t2] = [t2, t1];
    tEnter = Math.max(tEnter, t1);
    tExit = Math.min(tExit, t2);
    if (tEnter > tExit) return null;
  }

  // Defensive fallback: already overlapping at the current position (e.g. the
  // ball was nudged into the brick by an earlier frame). Never report a hit
  // beyond the end of the move.
  if (tEnter > 1) return collides(ball, brick) ? { t: 1, x: ball.x, y: ball.y } : null;

  return {
    t: tEnter,
    x: prevX + dx * tEnter,
    y: prevY + dy * tEnter,
  };
}
```

