// Deflects the ball off a brick at a known contact point `hit` (as returned by
// sweptBrickHit). The face that was hit is the axis with the SMALLER
// penetration of the ball's box into the brick rectangle (equal penetration =
// diagonal corner hit, both axes). The ball is flipped out of the brick (pushed
// back to just outside the rectangle, with a small epsilon so the next frame
// does not re-collide — sticky bounce) and the velocity component(s) of that
// face are reversed; the other component is left exactly as it was.
//
// Returns the face: 'x' (side), 'y' (top/bottom) or 'corner' (both).
export function bounceBall(ball, brick, hit) {
  const r = ball.r;
  const penX = Math.min(hit.x + r - brick.x, brick.x + brick.w - (hit.x - r));
  const penY = Math.min(hit.y + r - brick.y, brick.y + brick.h - (hit.y - r));
  const hitX = penX <= penY; // side face (or part of a corner)
  const hitY = penY <= penX; // top/bottom face (or part of a corner)
  const leftOf = hit.x < brick.x + brick.w / 2;
  const above = hit.y < brick.y + brick.h / 2;

  // Only reverse a component that actually points INTO the brick: this keeps
  // the bounce from re-firing when the ball is already leaving the rectangle.
  if (hitX && ((ball.vx > 0 && leftOf) || (ball.vx < 0 && !leftOf))) ball.vx = -ball.vx;
  if (hitY && ((ball.vy > 0 && above) || (ball.vy < 0 && !above))) ball.vy = -ball.vy;

  // Push the ball out of the rectangle (a hair beyond the face, so the next
  // frame's sweep starts cleanly outside and cannot re-trigger).
  const EPS = 0.01;
  if (hitX) ball.x = leftOf ? brick.x - r - EPS : brick.x + brick.w + r + EPS;
  if (hitY) ball.y = above ? brick.y - r - EPS : brick.y + brick.h + r + EPS;

  return hitX && hitY ? 'corner' : hitX ? 'x' : 'y';
}
```

