export function step(state, dt) {
  const { ball, paddle } = state;

  // Record where the move started: frame() sweeps the segment
  // (px, py) -> (x, y) to catch fast, tunnelling balls (issue #1).
  ball.px = ball.x;
  ball.py = ball.y;

  ball.x += ball.vx * dt;

