// --- Rendering (DOM): brick collision orchestration still lives in here ----

// Main render loop. For each live brick we detect the collision AND draw in
// the same pass: this is where logic and rendering are entangled (debt #2).
// The pure primitives (sweptBrickHit / bounceBall) are tested on their own.
export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks: detection + bounce + score + drawing, all in one place.
  //
  // The ball is swept from where the move started (recorded by step()) to
  // where it ended, so a fast ball that jumps over a brick in one frame is
  // still caught (tunnelling, #1). Every brick along the path breaks, but the
  // bounce itself applies exactly once — a seam hit overlaps two bricks in
  // the same pass, and two flips of the same axis cancel out (the ball would
  // go straight through).
  const prevX = state.ball.px ?? state.ball.x;
  const prevY = state.ball.py ?? state.ball.y;
  let bounce = null; // earliest contact along the path: { brick, contact }
  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    const contact = sweptBrickHit(prevX, prevY, state.ball, brick);
    if (contact) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
      if (!bounce || contact.t < bounce.contact.t) bounce = { brick, contact };
    }

    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }
  if (bounce) bounceBall(state.ball, bounce.brick, bounce.contact);

