cd game && node --input-type=module -e "
import { createState, step, frame } from './neon.js';
const ctx = new Proxy({}, { get: () => () => {}, set: (t,p,v) => (t[p]=v, true) });

// One brick, ball straight up from below. Expect: hit bottom face, bounce down, brick dead.
let st = createState(1);
for (const b of st.bricks) b.alive = false;
const t = st.bricks[35];
t.alive = true;
st.ball = { x: t.x + t.w/2, y: 300, r: 7, vx: 0, vy: -400 };
for (let i = 0; i < 40; i++) {
  step(st, 1/60);
  frame(ctx, st);
  if (!t.alive) {
    console.log('frame', i, '| brick broke | ball at', st.ball.x.toFixed(1), st.ball.y.toFixed(1), '| vx', st.ball.vx.toFixed(0), 'vy', st.ball.vy.toFixed(0));
    // keep simulating: must keep moving away, no re-kill/re-flip
    for (let j = 0; j < 20; j++) { step(st, 1/60); frame(ctx, st); }
    console.log('20 frames later: ball at', st.ball.x.toFixed(1), st.ball.y.toFixed(1), '| vy', st.ball.vy.toFixed(0), '| score', st.score);
    break;
  }
}
"
